  position: absolute; left: 1rem; bottom: 1rem;
  background: rgba(0,0,0,0.55);
  padding: .6rem .85rem;
  border-left: 3px solid var(--accent);
}
.carousel-controls {
  position: absolute; inset: 0;
  display: flex; justify-content: space-between; align-items: center;
  pointer-events: none;
}
.carousel-btn {
  pointer-events: auto;
  margin: 0 .8rem;
  width: 40px; height: 40px;
  border-radius: 50%; border: 1px solid var(--border);
  background: rgba(17,17,17,.7); color: white; cursor: pointer;
}

.cta-trial {
  padding: 2.4rem;
  border-radius: 10px;
  background: linear-gradient(120deg, #e63946 0%, #88101b 100%);
  color: white;
  box-shadow: 0 16px 40px rgba(230,57,70,0.25);
}
.cta-trial p { color: #ffeef0; max-width: 60ch; }

.toggle-wrap { display: inline-flex; border: 1px solid var(--border); border-radius: 999px; overflow: hidden; }
.toggle-btn {
  border: none; padding: .7rem 1.1rem; cursor: pointer;
  background: #1a1a1a; color: var(--text-muted); font-weight: 700;
}
.toggle-btn.active { background: var(--accent); color: #fff; }
.schedule-table {
  width: 100%; border-collapse: collapse; margin-top: 1rem;
  border: 1px solid var(--border); overflow: hidden; border-radius: 8px;
}
.schedule-table th, .schedule-table td { padding: .9rem .75rem; text-align: left; border-bottom: 1px solid var(--border); }
.schedule-table th { color: #fff; background: #1a1a1a; }
.schedule-table tr:nth-child(even) td { background: #151515; }

.filter-row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; }
select {
  background: #191919; color: #fff; border: 1px solid var(--border);
  border-radius: 6px; padding: .55rem .7rem;
}
.instructor-card img {
  height: 250px; width: 100%; object-fit: cover; border-radius: 6px;
  margin-bottom: .75rem;
}
.location-tag {
  display: inline-block;
  padding: .25rem .55rem;
  border-radius: 999px;
  background: #291012;
  color: #ff8a93;
  font-size: .8rem;
}

.faq-item { border-bottom: 1px solid var(--border); }
.faq-question {
  width: 100%; text-align: left; background: none; color: #fff;
  border: none; padding: 1rem 0; cursor: pointer; font-size: 1rem; font-weight: 700;
}
.faq-answer { max-height: 0; overflow: hidden; transition: max-height 260ms ease; color: var(--text-muted); }
.faq-item.open .faq-answer { max-height: 180px; padding-bottom: 1rem; }

.newsletter-form { display: flex; gap: .7rem; flex-wrap: wrap; }
.newsletter-form input {
  flex: 1; min-width: 210px; padding: .78rem .8rem;
  background: #1a1a1a; color: #fff; border: 1px solid var(--border); border-radius: 6px;
}
.inline-feedback { font-size: .92rem; margin-top: .5rem; }
.inline-feedback.error { color: #ff6b7a; }
.inline-feedback.success { color: var(--success); }

.site-footer { border-top: 1px solid var(--border); padding: 2rem 0; background: #0c0c0c; }
.footer-row { display: flex; justify-content: space-between; align-items: center; gap: 1rem; flex-wrap: wrap; }

@media (max-width: 900px) {
  .grid-2, .grid-3 { grid-template-columns: 1fr; }
  .slide { height: 300px; }
}
